problems.tests:
import dataclasses

from solution import *


class Animal:
    pass


class Dog(Animal):
    pass


def _type_error(action):
    try:
        action()
    except TypeError as error:
        return str(error)
    raise AssertionError('TypeError was not raised')


def _point():
    @validated
    class Point:
        x: int
        y: int = 0

    return Point


def test_example_1():
    """A valid point is a dataclass."""
    Point = _point()
    assert repr(Point(1, 2)).endswith('Point(x=1, y=2)')
    assert Point(1, 2) == Point(1, 2)
    assert dataclasses.is_dataclass(Point)


def test_example_2():
    """A wrong type names the field."""
    Point = _point()
    assert 'x' in _type_error(lambda: Point('1'))
    assert 'y' in _type_error(lambda: Point(1, 2.5))


def test_defaults():
    """A default fills a missing field."""
    assert _point()(5).y == 0


def test_later_assignment():
    """Changing a field later is checked too."""
    p = _point()(1)

    def assign():
        p.y = 1.5

    assert 'y' in _type_error(assign)
    p.y = 3
    assert p.y == 3


def test_other_attributes():
    """An attribute that isn't a field is not checked."""
    p = _point()(1)
    p.note = 'anything'
    assert p.note == 'anything'


def test_subclass_instances():
    """An instance of a subclass of the annotation is accepted."""
    @validated
    class Owner:
        pet: Animal

    assert isinstance(Owner(Dog()).pet, Dog)
    assert 'pet' in _type_error(lambda: Owner('cat'))


def test_default_factory():
    """field(default_factory=list) still works and is checked."""
    @validated
    class Bag:
        items: list = dataclasses.field(default_factory=list)

    a, b = Bag(), Bag()
    a.items.append(1)
    assert b.items == []
    assert 'items' in _type_error(lambda: Bag(items=(1, 2)))


def test_post_init():
    """__post_init__ runs, and what it stores in fields is checked."""
    @validated
    class Span:
        start: int
        end: int
        length: int = 0

        def __post_init__(self):
            self.length = self.end - self.start

    @validated
    class Ratio:
        top: int
        bottom: int
        value: int = 0

        def __post_init__(self):
            self.value = self.top / self.bottom

    assert Span(2, 5).length == 3
    assert 'value' in _type_error(lambda: Ratio(4, 2))

