problems.reference_solution:
import math
from numbers import Real


class Vector:
    """An immutable vector of numbers."""

    def __init__(self, *components):
        self._components = components

    def __repr__(self):
        return f'Vector({", ".join(map(repr, self._components))})'

    def __len__(self):
        return len(self._components)

    def __getitem__(self, index):
        return self._components[index]

    def __iter__(self):
        return iter(self._components)

    def __eq__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return self._components == other._components

    def __hash__(self):
        return hash(self._components)

    def __add__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return Vector(*(a + b for a, b in self._pairs(other)))

    def __sub__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return Vector(*(a - b for a, b in self._pairs(other)))

    def __mul__(self, factor):
        if not isinstance(factor, Real):
            return NotImplemented
        return Vector(*(a * factor for a in self._components))

    __rmul__ = __mul__

    def __abs__(self):
        return math.hypot(*self._components)

    def __bool__(self):
        return any(self._components)

    def _pairs(self, other):
        if len(self) != len(other):
            raise ValueError('vectors of different lengths')
        return zip(self._components, other._components)

